const input = $input.first().json;
const body = input.body || input;
const text = String(body.message_text || body.text || '').trim();
const sourceUrl = body.source_url || '';
const channel = String(body.channel_username || '').replace(/^@/, '');
const match = text.match(/https?:\/\/(?:www\.)?devkg\.com\/[^\s]+/i);
return [{ json: {
  text, sourceUrl, channel,
  messageId: body.message_id || '',
  messageDate: body.message_date || '',
  hasDevkg: Boolean(match),
  devkgUrl: match ? match[0].replace(/[),.;]+$/, '') : ''
} }];

const raw = $input.first().json;
const html = typeof raw === 'string' ? raw : (raw.body || raw.data || JSON.stringify(raw));
const clean = value => String(value || '')
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<[^>]+>/g, '\n')
  .replace(/&quot;/g, '\"').replace(/&#34;/g, '\"')
  .replace(/&amp;/g, '&').replace(/&nbsp;|&#160;/g, ' ')
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/\n\s*\n+/g, '\n').trim();
const text = clean(html);
const first = (re, fallback = 'Не указано') => (text.match(re)?.[1] || fallback).trim();
const title = clean(html.match(/<h1[^>]*>([\s\S]*?)<\/h1>/i)?.[1] || '') || first(/^([^\n]{4,140})/m);
const company = first(/Компания\s+([^\n]+)/i);
const workType = first(/Тип\s+([^\n]+)/i);
const salary = first(/(?:Оклад|Зарплата)\s+([^\n]+)/i);
const usernames = [...text.matchAll(/@([A-Za-z0-9_]{5,32})/g)].map(m => m[1]);
const telegram = usernames.find(u => !['devkg','findwork','remote','codifynews','backend_frontend_jobs'].includes(u.toLowerCase())) || '';
const description = (text.split(/Описание вакансии|Основные требования/i)[1] || text).split(/Похожие вакансии/i)[0].trim().slice(0, 5000);
const source = $('Normalize Public Post').first().json;
return [{ json: { title, company, workType, salary, telegram, description, sourceUrl: source.devkgUrl, channel: source.channel } }];

const source = $input.first().json;
const text = source.text || '';
const lines = text.split(/\n+/).map(s => s.trim()).filter(Boolean);
const firstLine = lines[0] || 'Вакансия из Telegram';
const title = firstLine.replace(/^[^:]{1,50}:\s*/, '').slice(0, 140);
const company = firstLine.includes(':') ? firstLine.split(':')[0].trim() : 'Не указано';
const salary = text.match(/(?:от|до)?\s*[$€]?\d[\d \u00a0,.]*(?:USD|KGS|сом|доллар)/i)?.[0] || 'Не указано';
const usernames = [...text.matchAll(/@([A-Za-z0-9_]{5,32})/g)].map(m => m[1]);
const telegram = usernames.find(u => !['devkg','findwork','remote','codifynews','backend_frontend_jobs'].includes(u.toLowerCase())) || '';
return [{ json: { title, company, workType: 'Из публикации канала', salary, telegram, description: text.slice(0, 5000), sourceUrl: source.sourceUrl, channel: source.channel } }];

const v = $input.first().json;
const full = `${v.title}\n${v.description}`.toLowerCase();
let score = 20;
const reasons = [];
const add = (points, label) => { score += points; reasons.push(`${points > 0 ? '+' : ''}${points}: ${label}`); };
if (/python|django|fastapi|backend|rest api|api integration/.test(full)) add(25, 'Python / Backend / API');
if (/frontend|html5?|css3?|javascript|react|next\.?js|верстк/.test(full)) add(23, 'Frontend-разработка');
if (/ai|искусственн|llm|automation|автоматизац|ai agent|агент/.test(full)) add(18, 'AI и автоматизация');
if (/project manager|product manager|координатор|управлен.*проект/.test(full)) add(18, 'Управление IT-проектом');
if (/postgres|mysql|mongodb|sql|database|баз.*данн/.test(full)) add(12, 'Базы данных');
if (/junior|студент|intern|стаж/.test(full)) add(12, 'Подходит студентам / Junior');
if (/git|figma|docker/.test(full)) add(5, 'Дополнительные совпадения');
if (/staff|tech lead|team lead|senior|lead developer|архитектор/.test(full)) add(-25, 'Требуется высокий уровень');
if (/8\+?\s*(?:years|лет)|7\+?\s*(?:years|лет)/.test(full)) add(-30, 'Требуется 7–8+ лет');
else if (/5\+?\s*(?:years|лет)|6\+?\s*(?:years|лет)/.test(full)) add(-20, 'Требуется 5–6+ лет');
if (/telecom|voip|freeswitch|kamailio|opensips|sip\b|rtp\b/.test(full)) add(-30, 'Узкая Telecom/VoIP специализация');
if (/devops|kubernetes|terraform|ansible/.test(full) && !/python|frontend|project manager/.test(full)) add(-18, 'Основной профиль DevOps');
score = Math.max(0, Math.min(100, score));
const decision = score >= 70 ? 'Приоритетный отклик' : score >= 30 ? 'Откликаемся' : 'Пропустить';
const draft = `Здравствуйте! Пишу по поводу вакансии «${v.title}»${v.company && v.company !== 'Не указано' ? ` в ${v.company}` : ''}. У меня есть опыт Full Stack разработки, работы с Python, JavaScript, REST API, базами данных и AI-инструментами, а также создания собственного проекта EcoPoints. Прикрепляю резюме. Буду рад обсудить вакансию подробнее.`;
return [{ json: { ...v, score, decision, reasons: reasons.join('\n') || 'Общие совпадения с IT-профилем', draft } }];

